import{_ as a}from"./chunks/missing_pack_icon.Bk5vr_Jt.js";import{_ as r,k as n,l as t,C as l,D as s,a6 as u,z as o,A as c,j as d}from"./chunks/framework.CR-GLmCb.js";const v=JSON.parse(`{"title":"Ore UI Customizer","description":"8Crafter's Ore UI Customizer","frontmatter":{"title":"Ore UI Customizer","page_title":"8Crafter's Ore UI Customizer","category":"Released","description":"8Crafter's Ore UI Customizer","tags":["nodejs_Web"],"thumbnail_url":"https://wiki.8crafter.com/main/assets/images/nodejs_program_cover_art/ore-ui-customizer.png","mentions":["8Crafter"]},"headers":[{"level":2,"title":"Main Features","slug":"main-features","link":"#main-features","children":[]},{"level":2,"title":"Next","slug":"next","link":"#next","children":[]}],"relativePath":"nodejs_programs/ore-ui-customizer.md","filePath":"nodejs_programs/ore-ui-customizer.md"}`),h={name:"nodejs_programs/ore-ui-customizer.md"};function p(m,e,f,w,g,b){const i=c("Button");return d(),n("div",null,[e[4]||(e[4]=t("img",{src:a,alt:"8Crafter's Ore UI Customizer Cover Art",title:"8Crafter's Ore UI Customizer Cover Art"},null,-1)),e[5]||(e[5]=t("br",null,null,-1)),l(i,{link:"https://www.8crafter.com/utilities/ore-ui-customizer"},{default:s(()=>e[0]||(e[0]=[o("Web App")])),_:1}),l(i,{link:"https://github.com/8Crafter-Studios/8Crafter.github.io"},{default:s(()=>e[1]||(e[1]=[o("GitHub")])),_:1}),l(i,{link:"/ouic/",target:"_self"},{default:s(()=>e[2]||(e[2]=[o(" Full Documentation ")])),_:1}),e[6]||(e[6]=u('<br><p>This is a web application that allows you to customize Ore UI in Minecraft Bedrock Edition.</p><p>This currently only works on PC and Android, unless you jailbreak your device.</p><p>Even though this web application is part of <a href="https://www.8crafter.com" target="_blank" rel="noreferrer">8Crafter&#39;s website</a>, you can also use it offline if you are able to use Node.js by just running my website on your device with Node.js. You just clone the repository to your device and run the index.js file. Then you can navigate to the page as normal.</p><p>Even though this web application fetches files, the files are loaded from the website, so downloading the respository will download the files too, so it will still work fully offline, and it will load much faster too, as all the resources are already on your device, the reason this works is because it fetches using relative urls, not static urls, so if you are running it on <a href="http://localhost:8213" target="_blank" rel="noreferrer">http://localhost:8213</a>, then it will load the resources from <a href="http://localhost:8213" target="_blank" rel="noreferrer">http://localhost:8213</a> and not from <a href="https://www.8crafter.com" target="_blank" rel="noreferrer">https://www.8crafter.com</a>.</p><p>When you run this web application locally on your device, it will run on port <code class="shiki"><span>8213</span></code> by default, so you can access it by going to <a href="http://localhost:8213/utilities/ore-ui-customizer.html" target="_blank" rel="noreferrer">http://localhost:8213/utilities/ore-ui-customizer.html</a> on the device it is running on, or to access it from another device on your local network, just find your device&#39;s local IP address and go to <a href="http://IP_ADDRESS:8213/utilities/ore-ui-customizer.html" target="_blank" rel="noreferrer">http://IP_ADDRESS:8213/utilities/ore-ui-customizer.html</a> (replace <code class="shiki"><span>IP_ADDRESS</span></code> with your local IP address).</p><h2 id="main-features" tabindex="-1">Main Features <a class="header-anchor" href="#main-features" aria-label="Permalink to &quot;Main Features&quot;">​</a></h2><p>It has many features, such as:</p><ul><li>Adding many custom menus to Ore UI, including but not limited to: <ul><li>8Crafter Utilities Menu <ul><li>Has many tabs, including: <ul><li>General <ul><li>Shows current version and configuration used when the customizer was used to customize your Ore UI.</li></ul></li><li>UIs <ul><li>Has buttons to open the other custom menus. <ul><li>Very usefull if you are on Android, because you can&#39;t use the keyboard shortcuts to open the other custom menus.</li></ul></li></ul></li><li>About <ul><li>Shows the current version of the customizer.</li><li>Shows the link to the webpage for the customizer.</li><li>Has contact information, including: <ul><li>Discord Server</li><li>GitHub Repository</li><li>Email</li></ul></li></ul></li></ul></li><li>Accessed with a button on the right side of the title bar, or with the <code class="shiki"><span>CTRL+ALT+SHIFT+M</span></code> shortcut.</li></ul></li><li>Small Corner Debug Overlay <ul><li>Shows debug info about mouse movement and held keys.</li><li>Accessed with the <code class="shiki"><span>CTRL+I</span></code> shortcut.</li></ul></li><li>Full JavaScript Console <ul><li>It is very advanced and has a lot of the features from the devtools console, including: <ul><li>Expanding objects and functions. <ul><li>It shows all properties and symbols, as well as the <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">__proto__</span></code> property (It shows as <code class="shiki"><span>[[Prototype]]</span></code>, just like in the devtools console).</li></ul></li><li>Logging console logs, debugs, errors, and warnings (with color coding).</li><li>The consolas font.</li><li>The little note that appears when you expand and object or function, that says &quot;This value was evaluated upon first expanding. It may have changed since then.&quot;.</li><li>etc.</li></ul></li><li>Accessed with the <code class="shiki"><span>CTRL+ALT+C</span></code> shortcut.</li></ul></li><li>View HTML Source Menu <ul><li>Accessed with the <code class="shiki"><span>CTRL+U</span></code> shortcut.</li></ul></li><li>Element Details Overlay <ul><li>Shows lots of information about the element that you are hovering over.</li><li>Shows the element&#39;s full CSS path.</li><li>Shows the element&#39;s number of children.</li><li>Shows the element&#39;s number of children, evaluated recursively.</li><li>Shows the element&#39;s client bounding box details (<code class="shiki"><span>left</span></code>, <code class="shiki"><span>top</span></code>, <code class="shiki"><span>right</span></code>, <code class="shiki"><span>bottom</span></code>, <code class="shiki"><span>x</span></code>, <code class="shiki"><span>y</span></code>, <code class="shiki"><span>width</span></code>, <code class="shiki"><span>height</span></code>).</li><li>Shows the element&#39;s attributes.</li><li>Accessed with the <code class="shiki"><span>CTRL+ALT+I</span></code> shortcut.</li></ul></li><li>CSS Editor <ul><li>Allows for editing the CSS of an element.</li><li>Allows for editing the Global CSS style sheet.</li><li>Allows for editing the CSS styles of the <code class="shiki"><span style="--shiki-light:#800000;--shiki-dark:#D7BA7D;">#root</span></code> element (The element that contains all the vanilla Ore UI, the custom menus from the customizer are outside of this element).</li><li>Accessed with the <code class="shiki"><span>CTRL+P</span></code> shortcut.</li></ul></li><li>etc.</li></ul></li><li>Adds the debug tab to the create and edit world screens.</li><li>Adds a bunch of new stuff to the debug tab.</li><li>Allows for changing the world seed through the debug tab.</li><li>Makes the hardcore mode toggle able to be enabled or disabled at any time.</li><li>Makes experimental toggles able to be disabled, even after the world has been saved with them on.</li><li>Makes the <code class="shiki"><span>Education Edition</span></code> toggle able to disabled, even after the world has been saved with it on.</li><li>Increases the maximum character limit for all text boxes.</li><li>Adds options for you to set the default game mode of your world to <code class="shiki"><span>Spectator</span></code> or <code class="shiki"><span>Default</span></code> (Setting it to <code class="shiki"><span>Default</span></code> breaks a lot of stuff). <ul><li>It also makes the <code class="shiki"><span>Adventure</span></code> game mode able to be set as the default game mode on the create world screen (Normally you can only do that on the edit world screen).</li></ul></li><li>Adds the world generator type dropdown to the advanced tab of the create and edit world screens. <ul><li>It lets you choose from the following world generator types: <ul><li>Legacy</li><li>Infinite World</li><li>Flat World</li><li>Void World</li></ul></li></ul></li><li>Lets you replace all the colors in the Ore UI, so you can create your own custom theme. <ul><li>It even has a preview in the customizer options for what the chosen colors will look like in-game.</li></ul></li><li>And so much more!</li></ul>',9)),e[7]||(e[7]=t("div",{class:"video-container"},[t("iframe",{src:"https://www.youtube.com/embed/tvWmJdXBsN4?si=UDUybhkuxKYplfcl",title:"How to Import .mcstructure Files into Worlds and Realms on MCBE (Mobile and PC)",frameborder:"0",allowfullscreen:"",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",referrerpolicy:"strict-origin-when-cross-origin",style:{width:"100%",height:"100%"}})],-1)),e[8]||(e[8]=t("h2",{id:"next",tabindex:"-1"},[o("Next "),t("a",{class:"header-anchor",href:"#next","aria-label":'Permalink to "Next"'},"​")],-1)),l(i,{link:"https://www.8crafter.com/utilities/ore-ui-customizer",target:"_self"},{default:s(()=>e[3]||(e[3]=[o(" Next: 8Crafter's Ore UI Customizer Website ")])),_:1})])}const C=r(h,[["render",p]]);export{v as __pageData,C as default};
